#include "nectar_assets/standin_world.h"

// Structure read once from the disc (read-only) for the models and parameter files
// of standin_world.h. Models: the joint parents and the collision parts
// { depth, joint, id, code, type, radius, centre, platform }. Nothing else of the
// models is here. tekipara: each file's words (version, eight ids, then the
// type's int and float parameters, whose counts differ per enemy). Boss parms:
// the tagged lists. The plants' light-flare groups and the models' geometry,
// textures and animations are not read.

